def ensure_ini(path="config.ini"):
    """若配置文件不存在，则生成默认模板"""
    if not os.path.exists(path):
        with open(path, "w", encoding="utf-8") as f:
            f.write(DEFAULT_INI)
        logger.info(f"已生成默认配置文件: {path}")


def load_ini(path="config.ini"):
    """读取 ini 并返回配置字典集合"""
    cp = configparser.ConfigParser()
    cp.read(path, encoding="utf-8")

    base_url = cp.get("flask", "base_url")

    flask_cfg = {
        "SECRET_KEY": cp.get("flask", "secret_key"),
        "HOST": cp.get("flask", "host"),
        "PORT": cp.getint("flask", "port"),
        "DEBUG": _to_bool(cp.get("flask", "debug")),
        "BASE_URL": base_url,
        "CORS_ORIGINS": [o.strip() for o in cp.get("flask", "cors_origins").split(",") if o.strip()],
    }
    db_cfg = {
        "DATABASE_URL": cp.get("database", "url"),
        "AUTH_DB": cp.get("database", "auth_db"),
    }
    biz_cfg = {
        "DEFAULT_PRICE": cp.getfloat("business", "default_price"),
        "DEFAULT_MAX_DOWNLOADS": cp.getint("business", "default_max_downloads"),
        "DEFAULT_EXPIRE_HOURS": cp.getint("business", "default_expire_hours"),
        "ADMIN_USERNAME": cp.get("business", "admin_username"),
        "ADMIN_PASSWORD": cp.get("business", "admin_password"),
    }
    auth_cfg = {
        "JWT_SECRET": cp.get("auth", "jwt_secret"),
        "JWT_EXPIRE_DAYS": cp.getint("auth", "jwt_expire_days"),
        "URL_PREFIX": cp.get("auth", "url_prefix"),
        "AUTH_DB": db_cfg["AUTH_DB"],
        "ENABLE_CAPTCHA": _to_bool(cp.get("auth", "enable_captcha")),
        "ENABLE_PASSWORD_LOGIN": _to_bool(cp.get("auth", "enable_password_login")),
        "ENABLE_SMS_LOGIN": _to_bool(cp.get("auth", "enable_sms_login")),
        "ENABLE_OAUTH": _to_bool(cp.get("auth", "enable_oauth")),
        "OAUTH_MOCK": _to_bool(cp.get("auth", "oauth_mock")),
        "TRUST_PROXY": _to_bool(cp.get("auth", "trust_proxy")),
        "RATE_LIMIT_ENABLED": _to_bool(cp.get("auth", "rate_limit_enabled")),
        "RL_LOGIN": {
            "limit": cp.getint("auth.rate_limit", "login_limit"),
            "window": cp.getint("auth.rate_limit", "login_window"),
        },
        "RL_REGISTER": {
            "limit": cp.getint("auth.rate_limit", "register_limit"),
            "window": cp.getint("auth.rate_limit", "register_window"),
        },
    }
    pay_cfg = {
        "alipay": {
            "appid": cp.get("alipay", "appid"),
            "private_key": cp.get("alipay", "private_key"),
            "public_key": cp.get("alipay", "public_key"),
            "notify_url": cp.get("alipay", "notify_url") or f"{base_url}/api/payment/alipay/notify",
            "sign_type": cp.get("alipay", "sign_type"),
            "debug": _to_bool(cp.get("alipay", "debug")),
        },
        "wechat": {
            "appid": cp.get("wechat", "appid"),
            "mch_id": cp.get("wechat", "mch_id"),
            "private_key": cp.get("wechat", "private_key"),
            "serial_no": cp.get("wechat", "serial_no"),
            "notify_url": cp.get("wechat", "notify_url") or f"{base_url}/api/payment/wechat/notify",
            "debug": _to_bool(cp.get("wechat", "debug")),
        },
    }
    return {
        "flask": flask_cfg,
        "database": db_cfg,
        "business": biz_cfg,
        "auth": auth_cfg,
        "pay": pay_cfg,
    }


