def generate_nonce(length=32):
    """生成随机字符串"""
    return ''.join(random.choices(ascii_letters + digits, k=length))


def current_timestamp():
    """当前 Unix 时间戳（秒级字符串）"""
    return str(int(datetime.now().timestamp()))


def current_datetime():
    """当前日期时间字符串 YYYY-MM-DD HH:MM:SS"""
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def sort_params(data):
    """字典按 key 排序"""
    return sorted(data.items())


def build_query_string(items, encode=False):
    """构建查询字符串"""
    if encode:
        return "&".join(f"{k}={quote_plus(str(v))}" for k, v in items)
    return "&".join(f"{k}={v}" for k, v in items)


def gen_uuid():
    return str(uuid.uuid4())


def gen_token():
    return secrets.token_urlsafe(32)


# ============================================================
# 密钥格式化工具
# ============================================================
class KeyFormatter:
    """RSA 密钥格式化工具"""

    @classmethod
    def clean_key(cls, key_str):
        """清理密钥：去掉 PEM 标记和空白"""
        if not key_str:
            return ""
        key_str = key_str.replace('\\n', '\n')
        markers = [
            '-----BEGIN RSA PRIVATE KEY-----', '-----END RSA PRIVATE KEY-----',
            '-----BEGIN PUBLIC KEY-----', '-----END PUBLIC KEY-----',
            '-----BEGIN PRIVATE KEY-----', '-----END PRIVATE KEY-----',
            '-----BEGIN CERTIFICATE-----', '-----END CERTIFICATE-----',
            '-----BEGIN ENCRYPTED PRIVATE KEY-----', '-----END ENCRYPTED PRIVATE KEY-----',
        ]
        for marker in markers:
            key_str = key_str.replace(marker, '')
        return re.sub(r'\s+', '', key_str)

    @classmethod
    def to_pem(cls, key_str, header, footer):
        """格式化为 PEM"""
        cleaned = cls.clean_key(key_str)
        if not cleaned:
            return ""
        lines = [cleaned[i:i + 64] for i in range(0, len(cleaned), 64)]
        return header + "\n" + "\n".join(lines) + "\n" + footer + "\n"

    @classmethod
    def diagnose(cls, key_str, name="key"):
        """密钥诊断"""
        if not key_str:
            logger.error(f"{name} is empty")
            return
        logger.info(f"=== {name} diagnosis ===")
        logger.info(f"Length: {len(key_str)}")
        logger.info(f"Preview: {key_str[:60]}...")
        cleaned = cls.clean_key(key_str)
        logger.info(f"Cleaned length: {len(cleaned)}")
        try:
            decoded = base64.b64decode(cleaned)
            logger.info(f"Decoded length: {len(decoded)} bytes")
            logger.info("Valid Base64: Yes")
        except Exception:
            logger.warning("Valid Base64: No")


# ============================================================
# RSA 签名工具
# ============================================================
class Signer:
    """RSA 签名工具类"""

    def __init__(self, private_key_str=None, public_key_str=None, debug=False):
        self.private_key = None
        self.public_key = None
        if private_key_str:
            if debug:
                KeyFormatter.diagnose(private_key_str, "private_key")
            self.private_key = self._load_key(private_key_str, is_private=True)
        if public_key_str:
            if debug:
                KeyFormatter.diagnose(public_key_str, "public_key")
            self.public_key = self._load_key(public_key_str, is_private=False)

    def _load_key(self, key_str, is_private=True):
        if not key_str or len(key_str) < 100:
            raise ValueError(f"Key too short ({len(key_str)} chars), please provide a valid key")
        key_type = "private" if is_private else "public"
        methods = [
            self._try_pkcs1_pem,
            self._try_pkcs8_pem,
            self._try_pkcs1_der,
            self._try_auto_detect,
            self._try_extract_from_key,
        ]
        errors = []
        for method in methods:
            try:
                result = method(key_str, is_private)
                if result:
                    logger.debug(f"Loaded {key_type} key via {method.__name__}")
                    return result
            except Exception as e:
                errors.append(f"{method.__name__}: {str(e)[:100]}")
        raise ValueError(
            f"Failed to load {key_type} key. Tried:\n" +
            "\n".join(f"  - {e}" for e in errors)
        )

    def _try_pkcs1_pem(self, key_str, is_private):
        if is_private:
            header = "-----BEGIN RSA PRIVATE KEY-----"
            footer = "-----END RSA PRIVATE KEY-----"
        else:
            header = "-----BEGIN RSA PUBLIC KEY-----"
            footer = "-----END RSA PUBLIC KEY-----"
        if header in key_str and footer in key_str:
            fixed = key_str.replace('\\n', '\n')
            if is_private:
                return rsa.PrivateKey.load_pkcs1(fixed.encode())
            return rsa.PublicKey.load_pkcs1(fixed.encode())
        pem = KeyFormatter.to_pem(key_str, header, footer)
        if is_private:
            return rsa.PrivateKey.load_pkcs1(pem.encode())
        return rsa.PublicKey.load_pkcs1(pem.encode())

    def _try_pkcs8_pem(self, key_str, is_private):
        if not is_private:
            return None
        header = "-----BEGIN PRIVATE KEY-----"
        footer = "-----END PRIVATE KEY-----"
        pem = KeyFormatter.to_pem(key_str, header, footer)
        return rsa.PrivateKey.load_pkcs1(pem.encode())

    def _try_pkcs1_der(self, key_str, is_private):
        cleaned = KeyFormatter.clean_key(key_str)
        der_data = base64.b64decode(cleaned)
        if is_private:
            return rsa.PrivateKey.load_pkcs1(der_data, format='DER')
        try:
            return rsa.PublicKey.load_pkcs1_openssl_der(der_data)
        except Exception:
            return rsa.PublicKey.load_pkcs1(der_data, format='DER')

    def _try_auto_detect(self, key_str, is_private):
        cleaned = KeyFormatter.clean_key(key_str)
        der_data = base64.b64decode(cleaned)
        if der_data and der_data[0] == 0x30:
            if is_private:
                try:
                    return rsa.PrivateKey.load_pkcs1(der_data, format='DER')
                except Exception:
                    pass
                try:
                    pem = "-----BEGIN PRIVATE KEY-----\n" + \
                          "\n".join(cleaned[i:i + 64] for i in range(0, len(cleaned), 64)) + \
                          "\n-----END PRIVATE KEY-----"
                    return rsa.PrivateKey.load_pkcs1(pem.encode())
                except Exception:
                    pass
            else:
                try:
                    return rsa.PublicKey.load_pkcs1_openssl_der(der_data)
                except Exception:
                    pass
        return None

    def _try_extract_from_key(self, key_str, is_private):
        if not is_private:
            return None
        if self.private_key:
            return None
        return None

    def sign(self, message, hash_method='SHA-256'):
        if not self.private_key:
            raise ValueError("Private key not configured")
        signature = rsa.sign(message.encode(), self.private_key, hash_method)
        return base64.b64encode(signature).decode()

    def verify(self, message, signature):
        if not self.public_key:
            raise ValueError("Public key not configured")
        try:
            rsa.verify(message.encode(), base64.b64decode(signature), self.public_key)
            return True
        except rsa.VerificationError:
            return False


# ============================================================
# 支付宝
# ============================================================
class AliPay:
    """支付宝支付类"""

    GATEWAY = "https://openapi.alipay.com/gateway.do"
    SANDBOX_GATEWAY = "https://openapi-sandbox.dl.alipaydev.com/gateway.do"

    PRODUCT_CODES = {
        'page': 'FAST_INSTANT_TRADE_PAY',
        'wap': 'QUICK_WAP_PAY',
        'app': 'QUICK_MSECURITY_PAY',
    }

    def __init__(self, config):
        self.appid = str(config.get('appid', ''))
        self.notify_url = config.get('notify_url', '')
        self.sign_type = config.get('sign_type', 'RSA2')
        self.debug = config.get('debug', False)
        self.gateway = self.SANDBOX_GATEWAY if self.debug else self.GATEWAY
        self.signer = Signer(
            config.get('private_key', ''),
            config.get('public_key', ''),
            debug=self.debug
        )

    def _build_params(self, method, biz_content, **extra):
        params = {
            "app_id": self.appid,
            "method": method,
            "charset": "utf-8",
            "sign_type": self.sign_type,
            "timestamp": current_datetime(),
            "version": "1.0",
            "biz_content": json.dumps(biz_content, separators=(',', ':')),
            **extra
        }
        return params

    def _sign_params(self, params):
        sorted_items = sort_params(params)
        raw_string = build_query_string(sorted_items)
        hash_method = 'SHA-1' if self.sign_type == "RSA" else 'SHA-256'
        sign = self.signer.sign(raw_string, hash_method)
        return build_query_string(sorted_items + [('sign', sign)], encode=True)

    def _request(self, method, biz_content):
        params = self._build_params(method, biz_content)
        if self.notify_url and 'notify_url' not in params:
            params['notify_url'] = self.notify_url
        url = f"{self.gateway}?{self._sign_params(params)}"
        response = requests.get(url).json()
        response_type = method.replace('.', '_') + '_response'
        return response.get(response_type, {})

    def page_pay(self, data):
        biz_content = {
            "subject": data['subject'],
            "out_trade_no": data['out_trade_no'],
            "total_amount": str(data['total_amount']),
            "product_code": self.PRODUCT_CODES['page']
        }
        params = self._build_params(
            'alipay.trade.page.pay', biz_content,
            return_url=data.get('return_url', ''),
            notify_url=data.get('notify_url', self.notify_url)
        )
        return f"{self.gateway}?{self._sign_params(params)}"

    def wap_pay(self, data):
        biz_content = {
            "subject": data['subject'],
            "out_trade_no": data['out_trade_no'],
            "total_amount": str(data['total_amount']),
            "product_code": self.PRODUCT_CODES['wap'],
            "quit_url": data.get('quit_url', '')
        }
        params = self._build_params(
            'alipay.trade.wap.pay', biz_content,
            return_url=data.get('return_url', ''),
            notify_url=data.get('notify_url', self.notify_url)
        )
        return f"{self.gateway}?{self._sign_params(params)}"

    def app_pay(self, data):
        biz_content = {
            "subject": data['subject'],
            "out_trade_no": data['out_trade_no'],
            "total_amount": str(data['total_amount']),
            "product_code": self.PRODUCT_CODES['app']
        }
        params = self._build_params(
            'alipay.trade.app.pay', biz_content,
            notify_url=data.get('notify_url', self.notify_url)
        )
        return self._sign_params(params)

    def precreate_pay(self, data):
        return self._request('alipay.trade.precreate', {
            "subject": data['subject'],
            "out_trade_no": data['out_trade_no'],
            "total_amount": str(data['total_amount'])
        })

    def pay(self, data):
        return self._request('alipay.trade.pay', {
            "subject": data['subject'],
            "out_trade_no": data['out_trade_no'],
            "total_amount": str(data['total_amount']),
            "scene": data.get('scene', 'bar_code'),
            "auth_code": data['auth_code']
        })

    def query(self, params):
        return self._request('alipay.trade.query', {
            k: v for k, v in params.items() if k in ('out_trade_no', 'trade_no')
        })

    def close(self, params):
        return self._request('alipay.trade.close', {
            k: v for k, v in params.items() if k in ('out_trade_no', 'trade_no')
        })

    def refund(self, params):
        return self._request('alipay.trade.refund', {
            k: v for k, v in params.items()
            if k in ('out_trade_no', 'trade_no', 'refund_amount', 'out_request_no')
        })

    def verify(self, data, signature):
        data.pop("sign_type", None)
        message = build_query_string(sort_params(data))
        return self.signer.verify(message, signature)


# ============================================================
# 微信支付 V3
# ============================================================
class WeChatPay:
    """微信支付 V3"""

    BASE_URL = "https://api.mch.weixin.qq.com"

    ENDPOINTS = {
        'native': '/v3/pay/transactions/native',
        'h5': '/v3/pay/transactions/h5',
        'app': '/v3/pay/transactions/app',
        'jsapi': '/v3/pay/transactions/jsapi',
        'query_id': '/v3/pay/transactions/id/{}',
        'query_out': '/v3/pay/transactions/out-trade-no/{}',
        'close': '/v3/pay/transactions/out-trade-no/{}/close',
        'refund': '/v3/refund/domestic/refunds',
    }

    def __init__(self, config):
        self.appid = str(config.get('appid', ''))
        self.mch_id = str(config.get('mch_id', ''))
        self.notify_url = config.get('notify_url', '')
        self.serial_no = str(config.get('serial_no', ''))
        self.debug = config.get('debug', False)
        self.signer = Signer(config.get('private_key', ''), debug=self.debug)

    def _get_auth_header(self, method, path, body=""):
        timestamp = current_timestamp()
        nonce = generate_nonce()
        message = f"{method}\n{path}\n{timestamp}\n{nonce}\n{body}\n"
        signature = self.signer.sign(message)
        return {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "Authorization": (
                f'WECHATPAY2-SHA256-RSA2048 '
                f'mchid="{self.mch_id}",'
                f'nonce_str="{nonce}",'
                f'timestamp="{timestamp}",'
                f'serial_no="{self.serial_no}",'
                f'signature="{signature}"'
            )
        }

    def _request(self, method, path, body=None):
        body_str = json.dumps(body) if body else ""
        headers = self._get_auth_header(method, path, body_str)
        response = requests.request(
            method,
            f"{self.BASE_URL}{path}",
            data=body_str if method in ("POST", "PUT") else None,
            headers=headers
        )
        return response.json() if response.text else {}

    def _create_order(self, path, data, extra_body=None):
        body = {
            "appid": self.appid,
            "mchid": self.mch_id,
            "description": data['body'],
            "out_trade_no": data['out_trade_no'],
            "notify_url": data.get('notify_url', self.notify_url),
            "amount": {"total": data['total_fee'], "currency": "CNY"},
        }
        if extra_body:
            body.update(extra_body)
        return self._request("POST", path, body)

    def _build_app_sign(self, prepay_id, template):
        timestamp = current_timestamp()
        nonce = generate_nonce()
        message = template.format(appid=self.appid, timestamp=timestamp,
                                  nonce=nonce, prepay_id=prepay_id)
        return {'timestamp': timestamp, 'nonce': nonce, 'sign': self.signer.sign(message)}

    def native_pay(self, data):
        result = self._create_order(self.ENDPOINTS['native'], data)
        return {'code_url': result.get('code_url', '')}

    def h5_pay(self, data):
        extra = {
            "scene_info": {
                "payer_client_ip": data.get('spbill_create_ip', '127.0.0.1'),
                "h5_info": {"type": "Wap"}
            }
        }
        result = self._create_order(self.ENDPOINTS['h5'], data, extra)
        return {'h5_url': result.get('h5_url', '')}

    def app_pay(self, data):
        result = self._create_order(self.ENDPOINTS['app'], data)
        prepay_id = result.get('prepay_id', '')
        sign_data = self._build_app_sign(prepay_id, "{appid}\n{timestamp}\n{nonce}\n{prepay_id}\n")
        return {
            'appid': self.appid,
            'partnerid': self.mch_id,
            'prepayid': prepay_id,
            'package': 'Sign=WXPay',
            'noncestr': sign_data['nonce'],
            'timestamp': sign_data['timestamp'],
            'sign': sign_data['sign']
        }

    def jsapi_pay(self, data):
        extra = {"payer": {"openid": data.get('openid', '')}}
        result = self._create_order(self.ENDPOINTS['jsapi'], data, extra)
        prepay_id = result.get('prepay_id', '')
        sign_data = self._build_app_sign(prepay_id, "{appid}\n{timestamp}\n{nonce}\nprepay_id={prepay_id}\n")
        return {
            'appId': self.appid,
            'timeStamp': sign_data['timestamp'],
            'nonceStr': sign_data['nonce'],
            'package': f"prepay_id={prepay_id}",
            'signType': 'RSA',
            'paySign': sign_data['sign']
        }

    def mini_pay(self, data):
        return self.jsapi_pay(data)

    def query(self, params):
        if 'transaction_id' in params:
            path = self.ENDPOINTS['query_id'].format(params['transaction_id'])
        else:
            path = self.ENDPOINTS['query_out'].format(params['out_trade_no'])
        return self._request("GET", f"{path}?mchid={self.mch_id}")

    def close(self, params):
        path = self.ENDPOINTS['close'].format(params['out_trade_no'])
        return self._request("POST", path, {"mchid": self.mch_id})

    def refund(self, params):
        body = {
            "out_trade_no": params.get('out_trade_no'),
            "out_refund_no": params.get('out_refund_no', params['out_trade_no'] + '_refund'),
            "amount": {
                "refund": params['refund_fee'],
                "total": params['total_fee'],
                "currency": "CNY"
            }
        }
        return self._request("POST", self.ENDPOINTS['refund'], body)

    def verify(self, data):
        message = f"{data.get('timestamp', '')}\n{data.get('nonce', '')}\n{data.get('body', '')}\n"
        return self.signer.verify(message, data.get('signature', ''))


# ============================================================
# 统一支付
# ============================================================
class Pay:
    """统一支付类"""

    PAY_MAP = {
        'alipay_page': ('alipay', 'page_pay'),
        'alipay_wap': ('alipay', 'wap_pay'),
        'alipay_app': ('alipay', 'app_pay'),
        'alipay_precreate': ('alipay', 'precreate_pay'),
        'alipay_pay': ('alipay', 'pay'),
        'wechat_native': ('wechat', 'native_pay'),
        'wechat_h5': ('wechat', 'h5_pay'),
        'wechat_app': ('wechat', 'app_pay'),
        'wechat_jsapi': ('wechat', 'jsapi_pay'),
        'wechat_mini': ('wechat', 'mini_pay'),
    }

    def __init__(self, config):
        self.alipay = self._safe_init(AliPay, config.get('alipay', {}), "Alipay")
        self.wechat = self._safe_init(WeChatPay, config.get('wechat', {}), "WeChatPay")

    def _safe_init(self, cls, config, name):
        try:
            return cls(config)
        except Exception as e:
            logger.warning(f"{name} init failed: {e}")
            return None

    def _get_order_data(self, order):
        total_amount = str(order['total_amount'])
        return {
            'subject': order.get('subject', ''),
            'body': order.get('body', order.get('subject', '')),
            'out_trade_no': order['out_trade_no'],
            'total_amount': total_amount,
            'total_fee': int(float(total_amount) * 100),
            'notify_url': order.get('notify_url'),
            'return_url': order.get('return_url'),
            'openid': order.get('openid'),
            'spbill_create_ip': order.get('spbill_create_ip', '127.0.0.1'),
            'quit_url': order.get('quit_url'),
            'auth_code': order.get('auth_code'),
            'scene': order.get('scene', 'bar_code'),
        }

    def create(self, pay_type, **order):
        if pay_type not in self.PAY_MAP:
            raise ValueError(f"Unsupported: {pay_type}")
        channel, method = self.PAY_MAP[pay_type]
        instance = getattr(self, channel)
        if not instance:
            raise RuntimeError(f"{channel} not available")
        return getattr(instance, method)(self._get_order_data(order))

    def _delegate(self, action, pay_type, **params):
        channel = 'alipay' if pay_type.startswith('alipay') else 'wechat'
        instance = getattr(self, channel)
        if not instance:
            raise RuntimeError(f"{channel} not available")
        return getattr(instance, action)(params)

    def query(self, pay_type, **params):
        return self._delegate('query', pay_type, **params)

    def close(self, pay_type, **params):
        return self._delegate('close', pay_type, **params)

    def refund(self, pay_type, **params):
        return self._delegate('refund', pay_type, **params)

    def verify(self, pay_type, data, signature=None):
        if pay_type.startswith('alipay'):
            return self.alipay.verify(data, signature) if self.alipay else False
        return self.wechat.verify(data) if self.wechat else False


# ============================================================
# FakeRedis —— 内存版 Redis
# ============================================================
class FakeRedis:
    """内存 KV 存储，支持 set/get/delete/exists/ttl/incr"""

    def __init__(self):
        self._data = {}

    def set(self, key, value, ex=None):
        self._data[key] = (value, time.time() + ex if ex else None)

    def get(self, key):
        item = self._data.get(key)
        if not item:
            return None
        v, exp = item
        if exp and exp < time.time():
            del self._data[key]
            return None
        return v

    def delete(self, key):
        self._data.pop(key, None)

    def exists(self, key):
        return self.get(key) is not None

    def ttl(self, key):
        item = self._data.get(key)
        if not item:
            return -2
        _, exp = item
        if exp is None:
            return -1
        remain = int(exp - time.time())
        if remain <= 0:
            del self._data[key]
            return -2
        return remain

    def incr(self, key, amount=1):
        current = self.get(key)
        try:
            current = int(current) if current is not None else 0
        except (TypeError, ValueError):
            current = 0
        new_val = current + amount
        item = self._data.get(key)
        if item and item[1]:
            self._data[key] = (str(new_val), item[1])
        else:
            self._data[key] = (str(new_val), None)
        return new_val


