# OAuth Provider
# ============================================================
class BaseOAuthProvider:
    name = "base"

    def __init__(self, config=None):
        self.config = config or {}

    def authorize_url(self, state):
        raise NotImplementedError

    def fetch_user(self, code):
        raise NotImplementedError


class MockProvider(BaseOAuthProvider):
    """模拟 OAuth Provider"""

    def __init__(self, name):
        self.name = name

    def authorize_url(self, state):
        return None

    def fetch_user(self, code):
        seed = hashlib.md5(code.encode()).hexdigest()[:10]
        return {
            "open_id": f"mock_openid_{self.name}_{seed}",
            "union_id": f"mock_union_{self.name}",
            "nickname": f"{self.name}用户_{seed[-4:]}",
            "avatar": f"https://api.dicebear.com/7.x/identicon/svg?seed={seed}",
        }


# ============================================================
# AuthManager
# ============================================================
class AuthManager:
    """认证管理器"""

    DEFAULT_CONFIG = {
        "JWT_SECRET": "change-me",
        "JWT_ALGORITHM": "HS256",
        "JWT_EXPIRE_DAYS": 7,
        "URL_PREFIX": "/api/auth",
        "BLUEPRINT_NAME": "auth_kit",
        "ENABLE_CAPTCHA": True,
        "ENABLE_PASSWORD_LOGIN": True,
        "ENABLE_SMS_LOGIN": True,
        "ENABLE_OAUTH": True,
        "CAPTCHA_EXPIRE": 120,
        "CAPTCHA_LENGTH": 4,
        "SMS_CODE_EXPIRE": 300,
        "SMS_SEND_INTERVAL": 60,
        "SMS_MOCK_RETURN": True,
        "OAUTH_MOCK": True,
        "OAUTH_STATE_EXPIRE": 300,
        "OAUTH_DONE_PATH": "/oauth-done",
        "PASSWORD_MIN_LENGTH": 6,
        "USERNAME_MIN_LENGTH": 3,
        "USERNAME_MAX_LENGTH": 20,
        "PHONE_REGEX": r"1\d{10}",
        "AUTH_DB": "auth.db",
        "RATE_LIMIT_ENABLED": True,
        "TRUST_PROXY": False,
        "RATE_LIMIT_FAIL_OPEN": True,
        "RL_REGISTER": {"limit": 5, "window": 3600},
        "RL_LOGIN": {"limit": 10, "window": 60},
        "RL_SMS_SEND_IP": {"limit": 20, "window": 3600},
        "RL_SMS_SEND_PH": {"limit": 10, "window": 86400},
        "RL_SMS_LOGIN": {"limit": 5, "window": 600},
        "RL_OAUTH": {"limit": 30, "window": 60},
        "RL_ME": {"limit": 60, "window": 60},
        "ACCOUNT_FAIL_LIMIT": 5,
        "ACCOUNT_FAIL_LOCK": 300,
    }

    def __init__(self, app, db=None, config=None, redis_client=None,
                 sms_sender=None, oauth_providers=None):
        self.app = app
        self.config = {**self.DEFAULT_CONFIG, **(config or {})}
        self.redis = redis_client or FakeRedis()
        self.sms_sender = sms_sender or self._default_sms_sender
        self.providers = {}
        self.db_path = self.config["AUTH_DB"]
        self._register_providers(oauth_providers)
        self.app.config.setdefault("JWT_SECRET", self.config["JWT_SECRET"])

    def _conn(self):
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        return conn

    def init_db(self, db_path=None):
        if db_path:
            self.db_path = db_path
        os.makedirs(os.path.dirname(os.path.abspath(self.db_path)), exist_ok=True)
        conn = self._conn()
        c = conn.cursor()
        c.execute('''
            CREATE TABLE IF NOT EXISTS auth_user (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE,
                password_hash TEXT,
                phone TEXT UNIQUE,
                nickname TEXT,
                avatar TEXT,
                is_active INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        c.execute('''
            CREATE TABLE IF NOT EXISTS auth_oauth_account (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                provider TEXT,
                open_id TEXT,
                union_id TEXT,
                nickname TEXT,
                avatar TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(provider, open_id)
            )
        ''')
        conn.commit()
        conn.close()

    def _register_providers(self, custom):
        if custom:
            for name, p in custom.items():
                p.name = name
                self.providers[name] = p
        elif self.config["OAUTH_MOCK"]:
            for name in ("wechat", "qq", "weibo", "github"):
                self.providers[name] = MockProvider(name)

    def _default_sms_sender(self, phone, code):
        print(f"\n>>> [AuthKit 模拟短信] {phone} 验证码: {code}\n")
        return True

    def _user_by_id(self, uid):
        conn = self._conn()
        row = conn.execute("SELECT * FROM auth_user WHERE id = ?", (uid,)).fetchone()
        conn.close()
        return row

    def _user_to_dict(self, row):
        if not row:
            return None
        return {
            "id": row["id"],
            "username": row["username"],
            "phone": row["phone"],
            "nickname": row["nickname"],
            "avatar": row["avatar"],
            "is_active": bool(row["is_active"]),
        }

    def make_token(self, user_id):
        payload = {
            "sub": str(user_id),
            "exp": datetime.utcnow() + timedelta(days=self.config["JWT_EXPIRE_DAYS"]),
            "iat": datetime.utcnow(),
        }
        return jwt.encode(payload, self.config["JWT_SECRET"],
                          algorithm=self.config["JWT_ALGORITHM"])

    def parse_token(self, token):
        try:
            return int(jwt.decode(token, self.config["JWT_SECRET"],
                                  algorithms=[self.config["JWT_ALGORITHM"]])["sub"])
        except Exception:
            return None

    def current_user(self):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return None
        uid = self.parse_token(auth[7:])
        if not uid:
            return None
        row = self._user_by_id(uid)
        if row and row["is_active"]:
            return row
        return None

    def login_required(self, fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            u = self.current_user()
            if not u:
                return jsonify({"code": 1, "msg": "未登录或 token 失效"}), 401
            request.auth_user = type("U", (), {
                "id": u["id"], "username": u["username"],
                "phone": u["phone"], "nickname": u["nickname"],
                "avatar": u["avatar"],
            })()
            return fn(*a, **kw)
        return wrapper

    def _ok(self, data=None, msg="ok", code=200):
        body = {"code": 0, "msg": msg}
        if data is not None:
            body["data"] = data
        return jsonify(body), code

    def _fail(self, msg="error", code=400):
        return jsonify({"code": 1, "msg": msg}), code

    def _gen_captcha(self):
        if ImageCaptcha is None:
            raise RuntimeError("pip install captcha pillow")
        code = "".join(random.choices(string.ascii_uppercase + string.digits,
                                      k=self.config["CAPTCHA_LENGTH"]))
        cid = secrets.token_hex(16)
        self.redis.set(f"captcha:{cid}", code.lower(), ex=self.config["CAPTCHA_EXPIRE"])
        img = ImageCaptcha(width=120, height=44)
        buf = io.BytesIO()
        img.write(code, buf)
        buf.seek(0)
        return cid, buf

    def _verify_captcha(self, cid, code):
        if not self.config["ENABLE_CAPTCHA"]:
            return True
        if not cid or not code:
            return False
        k = f"captcha:{cid}"
        stored = self.redis.get(k)
        self.redis.delete(k)
        return stored is not None and stored == code.strip().lower()

    def _safe_redirect(self, target):
        if not target:
            return None
        if not target.startswith("/") or target.startswith("//"):
            return None
        return target

    def _client_ip(self):
        if self.config.get("TRUST_PROXY"):
            xff = request.headers.get("X-Forwarded-For", "")
            if xff:
                return xff.split(",")[0].strip()
        return request.remote_addr or "unknown"

    def _resolve_identity(self, by):
        if by == "ip":
            return self._client_ip()
        if by == "phone":
            data = request.get_json(silent=True) or {}
            return (data.get("phone") or "unknown").strip()
        if by == "user":
            u = getattr(request, "auth_user", None)
            if u:
                return str(u.id)
            return f"anon:{self._client_ip()}"
        return "global"

    def _rate_key(self, scope, by, identity):
        return f"ratelimit:{scope}:{by}:{identity}"

    def _build_limit_response(self, ttl=None, msg="请求过于频繁，请稍后重试"):
        body = {"code": 1, "msg": msg}
        if ttl:
            body["retry_after"] = ttl
        resp = jsonify(body)
        resp.status_code = 429
        if ttl:
            resp.headers["Retry-After"] = str(ttl)
        return resp

    def _safe_redis(self, func, *args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception:
            try:
                current_app.logger.warning("限流 Redis 异常", exc_info=True)
            except Exception:
                pass
            if self.config.get("RATE_LIMIT_FAIL_OPEN", True):
                return None
            raise

    def rate_limit(self, scope, limit, window, by="ip", identity_fn=None):
        def decorator(fn):
            @wraps(fn)
            def wrapper(*args, **kwargs):
                if not self.config.get("RATE_LIMIT_ENABLED", True):
                    return fn(*args, **kwargs)
                identity = identity_fn() if identity_fn else self._resolve_identity(by)
                key = self._rate_key(scope, by, identity)
                raw = self._safe_redis(self.redis.get, key)
                if raw is None:
                    self._safe_redis(self.redis.set, key, "1", ex=window)
                    return fn(*args, **kwargs)
                try:
                    current = int(raw)
                except (TypeError, ValueError):
                    current = 0
                if current >= limit:
                    ttl = self._safe_redis(self.redis.ttl, key)
                    if ttl is None or ttl < 0:
                        ttl = window
                    return self._build_limit_response(ttl)
                self._safe_redis(self.redis.incr, key)
                return fn(*args, **kwargs)
            return wrapper
        return decorator

    def sliding_window_limit(self, scope, limit, window, by="ip", identity_fn=None):
        def decorator(fn):
            @wraps(fn)
            def wrapper(*args, **kwargs):
                if not self.config.get("RATE_LIMIT_ENABLED", True):
                    return fn(*args, **kwargs)
                identity = identity_fn() if identity_fn else self._resolve_identity(by)
                key = self._rate_key(scope + ":sliding", by, identity)
                now = time.time()
                raw = self._safe_redis(self.redis.get, key)
                if raw is None:
                    items = []
                else:
                    try:
                        items = json.loads(raw)
                    except (TypeError, ValueError):
                        items = []
                items = [t for t in items if t > now - window]
                if len(items) >= limit:
                    ttl = int(items[0] + window - now) + 1
                    return self._build_limit_response(ttl)
                items.append(now)
                self._safe_redis(self.redis.set, key, json.dumps(items), ex=window)
                return fn(*args, **kwargs)
            return wrapper
        return decorator

    def token_bucket_limit(self, scope, capacity, refill_rate, by="ip", identity_fn=None):
        def decorator(fn):
            @wraps(fn)
            def wrapper(*args, **kwargs):
                if not self.config.get("RATE_LIMIT_ENABLED", True):
                    return fn(*args, **kwargs)
                identity = identity_fn() if identity_fn else self._resolve_identity(by)
                key = self._rate_key(scope + ":bucket", by, identity)
                now = time.time()
                raw = self._safe_redis(self.redis.get, key)
                if raw:
                    try:
                        tokens, last = json.loads(raw)
                    except (TypeError, ValueError):
                        tokens, last = capacity, now
                    tokens = min(capacity, tokens + (now - last) * refill_rate)
                else:
                    tokens, last = capacity, now
                if tokens < 1:
                    ttl = max(1, int((1 - tokens) / refill_rate) + 1)
                    return self._build_limit_response(ttl)
                tokens -= 1
                ex = max(1, int(capacity / refill_rate) + 1)
                self._safe_redis(self.redis.set, key, json.dumps([tokens, now]), ex=ex)
                return fn(*args, **kwargs)
            return wrapper
        return decorator

    def _account_fail_key(self, username):
        return f"login:fail:{username.lower()}"

    def _check_account_locked(self, username):
        key = self._account_fail_key(username)
        fails_raw = self._safe_redis(self.redis.get, key)
        if fails_raw is None:
            return False, 0
        try:
            fails = int(fails_raw)
        except (TypeError, ValueError):
            fails = 0
        if fails >= self.config["ACCOUNT_FAIL_LIMIT"]:
            ttl = self._safe_redis(self.redis.ttl, key) or self.config["ACCOUNT_FAIL_LOCK"]
            return True, ttl
        return False, 0

    def _record_login_fail(self, username):
        key = self._account_fail_key(username)
        self._safe_redis(self.redis.incr, key)
        self._safe_redis(self.redis.set, key,
                         self._safe_redis(self.redis.get, key) or "1",
                         ex=self.config["ACCOUNT_FAIL_LOCK"])

    def _clear_login_fail(self, username):
        self._safe_redis(self.redis.delete, self._account_fail_key(username))

    def _oauth_login(self, provider, open_id, union_id=None, nickname=None, avatar=None):
        conn = self._conn()
        c = conn.cursor()
        acct = None
        if provider == "wechat" and union_id:
            acct = c.execute(
                "SELECT * FROM auth_oauth_account WHERE provider=? AND union_id=?",
                (provider, union_id)
            ).fetchone()
        if not acct:
            acct = c.execute(
                "SELECT * FROM auth_oauth_account WHERE provider=? AND open_id=?",
                (provider, open_id)
            ).fetchone()
        if acct:
            user_id = acct["user_id"]
        else:
            c.execute(
                "INSERT INTO auth_user (nickname, avatar) VALUES (?, ?)",
                (nickname, avatar)
            )
            user_id = c.lastrowid
            c.execute('''
                INSERT INTO auth_oauth_account
                  (user_id, provider, open_id, union_id, nickname, avatar)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (user_id, provider, open_id, union_id, nickname, avatar))
        conn.commit()
        conn.close()
        return user_id

    def init_routes(self):
        bp = Blueprint(self.config["BLUEPRINT_NAME"], __name__,
                       url_prefix=self.config["URL_PREFIX"])
        cfg = self.config

        if cfg["ENABLE_CAPTCHA"]:
            @bp.get("/captcha")
            def captcha():
                cid, buf = self._gen_captcha()
                resp = send_file(buf, mimetype="image/png")
                resp.headers["X-Captcha-Id"] = cid
                resp.headers["Cache-Control"] = "no-store"
                return resp

        @bp.post("/register")
        @self.rate_limit(scope="register", limit=cfg["RL_REGISTER"]["limit"],
                         window=cfg["RL_REGISTER"]["window"], by="ip")
        def register():
            data = request.get_json() or {}
            username = (data.get("username") or "").strip()
            password = data.get("password") or ""

            if len(username) < cfg["USERNAME_MIN_LENGTH"] or len(username) > cfg["USERNAME_MAX_LENGTH"]:
                return self._fail(f"用户名长度 {cfg['USERNAME_MIN_LENGTH']}-{cfg['USERNAME_MAX_LENGTH']}")
            if len(password) < cfg["PASSWORD_MIN_LENGTH"]:
                return self._fail(f"密码至少 {cfg['PASSWORD_MIN_LENGTH']} 位")
            if not self._verify_captcha(data.get("captcha_id"), data.get("captcha")):
                return self._fail("图形验证码错误")

            conn = self._conn()
            c = conn.cursor()
            if c.execute("SELECT id FROM auth_user WHERE username=?", (username,)).fetchone():
                conn.close()
                return self._fail("用户名已存在", 409)

            c.execute(
                "INSERT INTO auth_user (username, password_hash, nickname) VALUES (?, ?, ?)",
                (username, generate_password_hash(password), username)
            )
            uid = c.lastrowid
            conn.commit()
            user = self._user_to_dict(self._user_by_id(uid))
            conn.close()
            return self._ok({"token": self.make_token(uid), "user": user}, "注册成功", 201)

        if cfg["ENABLE_PASSWORD_LOGIN"]:
            @bp.post("/login")
            @self.rate_limit(scope="login", limit=cfg["RL_LOGIN"]["limit"],
                             window=cfg["RL_LOGIN"]["window"], by="ip")
            def login():
                data = request.get_json() or {}
                username = (data.get("username") or "").strip()

                if not self._verify_captcha(data.get("captcha_id"), data.get("captcha")):
                    return self._fail("图形验证码错误")

                locked, ttl = self._check_account_locked(username)
                if locked:
                    return self._build_limit_response(
                        ttl=ttl, msg=f"账号已锁定，请 {ttl} 秒后重试")

                conn = self._conn()
                row = conn.execute(
                    "SELECT * FROM auth_user WHERE username=?", (username,)
                ).fetchone()
                conn.close()

                if not row or not row["password_hash"] or \
                   not check_password_hash(row["password_hash"], data.get("password") or ""):
                    self._record_login_fail(username)
                    return self._fail("用户名或密码错误", 401)
                if not row["is_active"]:
                    return self._fail("账号已被禁用", 403)

                self._clear_login_fail(username)

                return self._ok(
                    {"token": self.make_token(row["id"]),
                     "user": self._user_to_dict(row)},
                    "登录成功")

        if cfg["ENABLE_SMS_LOGIN"]:
            @bp.post("/sms/send")
            @self.rate_limit(scope="sms_send_ip",
                             limit=cfg["RL_SMS_SEND_IP"]["limit"],
                             window=cfg["RL_SMS_SEND_IP"]["window"], by="ip")
            @self.rate_limit(scope="sms_send_phone",
                             limit=cfg["RL_SMS_SEND_PH"]["limit"],
                             window=cfg["RL_SMS_SEND_PH"]["window"], by="phone")
            def sms_send():
                data = request.get_json() or {}
                phone = (data.get("phone") or "").strip()

                if not re.fullmatch(cfg["PHONE_REGEX"], phone):
                    return self._fail("手机号格式不正确")
                if not self._verify_captcha(data.get("captcha_id"), data.get("captcha")):
                    return self._fail("图形验证码错误")
                if self.redis.exists(f"sms:limit:{phone}"):
                    return self._fail("发送过于频繁")

                code = str(random.randint(100000, 999999))
                self.redis.set(f"sms:code:{phone}", code, ex=cfg["SMS_CODE_EXPIRE"])
                self.redis.set(f"sms:limit:{phone}", 1, ex=cfg["SMS_SEND_INTERVAL"])

                if not self.sms_sender(phone, code):
                    return self._fail("短信发送失败", 500)

                resp = {"mock_code": code} if cfg["SMS_MOCK_RETURN"] else None
                return self._ok(resp, "验证码已发送")

            @bp.post("/sms/login")
            @self.rate_limit(scope="sms_login", limit=cfg["RL_SMS_LOGIN"]["limit"],
                             window=cfg["RL_SMS_LOGIN"]["window"], by="phone")
            def sms_login():
                data = request.get_json() or {}
                phone = (data.get("phone") or "").strip()
                code = (data.get("code") or "").strip()

                stored = self.redis.get(f"sms:code:{phone}")
                if not stored or stored != code:
                    return self._fail("验证码错误或已过期", 401)
                self.redis.delete(f"sms:code:{phone}")

                conn = self._conn()
                c = conn.cursor()
                row = c.execute("SELECT * FROM auth_user WHERE phone=?", (phone,)).fetchone()

                if not row:
                    c.execute(
                        "INSERT INTO auth_user (phone, nickname) VALUES (?, ?)",
                        (phone, f"用户{phone[-4:]}")
                    )
                    uid = c.lastrowid
                    conn.commit()
                    row = c.execute("SELECT * FROM auth_user WHERE id=?", (uid,)).fetchone()
                else:
                    uid = row["id"]
                conn.close()

                return self._ok(
                    {"token": self.make_token(uid), "user": self._user_to_dict(row)},
                    "登录成功")

        if cfg["ENABLE_OAUTH"]:
            @bp.get("/oauth/<provider>/redirect")
            @self.rate_limit(scope="oauth_redirect", limit=cfg["RL_OAUTH"]["limit"],
                             window=cfg["RL_OAUTH"]["window"], by="ip")
            def oauth_redirect(provider):
                if provider not in self.providers:
                    return self._fail("不支持的平台", 404)

                state = secrets.token_urlsafe(24)
                self.redis.set(f"oauth:state:{state}", provider, ex=cfg["OAUTH_STATE_EXPIRE"])

                redirect_to = self._safe_redirect(request.args.get("redirect")) or cfg["OAUTH_DONE_PATH"]

                if cfg["OAUTH_MOCK"]:
                    mock_code = f"mock_{provider}_{secrets.token_hex(6)}"
                    return redirect(
                        f"{cfg['URL_PREFIX']}/oauth/{provider}/callback"
                        f"?code={mock_code}&state={state}&redirect={redirect_to}"
                    )

                url = self.providers[provider].authorize_url(state)
                if not url:
                    return self._fail("平台配置缺失", 500)
                return redirect(url)

            @bp.get("/oauth/<provider>/callback")
            @self.rate_limit(scope="oauth_callback", limit=cfg["RL_OAUTH"]["limit"],
                             window=cfg["RL_OAUTH"]["window"], by="ip")
            def oauth_callback(provider):
                if provider not in self.providers:
                    return self._fail("不支持的平台", 404)

                code = request.args.get("code")
                state = request.args.get("state")
                redirect_to = self._safe_redirect(request.args.get("redirect")) or cfg["OAUTH_DONE_PATH"]

                k = f"oauth:state:{state}"
                saved = self.redis.get(k)
                self.redis.delete(k)
                if not saved or saved != provider:
                    return redirect(f"{redirect_to}?error=state+invalid+or+expired")
                if not code:
                    return redirect(f"{redirect_to}?error=missing+code")

                try:
                    info = self.providers[provider].fetch_user(code)
                except Exception as e:
                    current_app.logger.exception("OAuth 失败")
                    return redirect(f"{redirect_to}?error=" + str(e).replace(" ", "+"))

                uid = self._oauth_login(provider, info["open_id"], info.get("union_id"),
                                        info.get("nickname"), info.get("avatar"))
                token = self.make_token(uid)

                if request.args.get("redirect"):
                    return redirect(f"{redirect_to}?token={token}")
                user = self._user_to_dict(self._user_by_id(uid))
                return self._ok({"token": token, "user": user})

        @bp.get("/me")
        @self.login_required
        @self.rate_limit(scope="me", limit=cfg["RL_ME"]["limit"],
                         window=cfg["RL_ME"]["window"], by="user")
        def me():
            user = self.current_user()
            if not user:
                return self._fail("未登录或 token 失效", 401)

            conn = self._conn()
            rows = conn.execute(
                "SELECT provider FROM auth_oauth_account WHERE user_id=?",
                (user["id"],)
            ).fetchall()
            conn.close()

            data = self._user_to_dict(user)
            data["bindings"] = [r["provider"] for r in rows]
            return self._ok(data)

        @bp.post("/logout")
        def logout():
            return self._ok(msg="已退出")

        self.app.register_blueprint(bp)
        return bp


