def define_models():
    """在 db 初始化之后定义模型"""

    class Product(db.Model):
        __tablename__ = 'products'
        id = db.Column(db.Integer, primary_key=True)
        uuid = db.Column(db.String(36), unique=True, default=gen_uuid, index=True)
        title = db.Column(db.String(200), nullable=False)
        description = db.Column(db.Text, default='')
        storage_path = db.Column(db.String(500), nullable=False)
        original_filename = db.Column(db.String(200), nullable=False)
        file_size = db.Column(db.BigInteger, default=0)
        file_type = db.Column(db.String(50), default='')
        file_hash = db.Column(db.String(64), default='')
        mime_type = db.Column(db.String(100), default='application/octet-stream')
        price = db.Column(db.Float, nullable=False, default=9.90)
        original_price = db.Column(db.Float, nullable=True)
        sales_count = db.Column(db.Integer, default=0)
        view_count = db.Column(db.Integer, default=0)
        is_active = db.Column(db.Boolean, default=True, index=True)
        is_featured = db.Column(db.Boolean, default=False)
        category = db.Column(db.String(100), default='', index=True)
        tags = db.Column(db.String(200), default='')
        max_downloads = db.Column(db.Integer, default=3)
        expire_hours = db.Column(db.Integer, default=24)
        created_at = db.Column(db.DateTime, default=datetime.utcnow)
        updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

        def to_dict(self):
            return {
                'id': self.id, 'uuid': self.uuid, 'title': self.title,
                'description': self.description, 'original_filename': self.original_filename,
                'file_size': self.file_size, 'file_type': self.file_type,
                'price': self.price, 'original_price': self.original_price,
                'sales_count': self.sales_count, 'view_count': self.view_count,
                'category': self.category,
                'tags': [t.strip() for t in (self.tags or '').split(',') if t.strip()],
                'is_active': self.is_active, 'is_featured': self.is_featured,
                'max_downloads': self.max_downloads, 'expire_hours': self.expire_hours,
                'created_at': self.created_at.isoformat() if self.created_at else None,
                'discount': round((1 - self.price / self.original_price) * 100)
                    if self.original_price and self.original_price > self.price else 0
            }

    class Order(db.Model):
        __tablename__ = 'orders'
        id = db.Column(db.Integer, primary_key=True)
        order_id = db.Column(db.String(64), unique=True, nullable=False, index=True)
        product_id = db.Column(db.Integer, db.ForeignKey('products.id'), nullable=False)
        user_id = db.Column(db.Integer, nullable=True, index=True)
        amount = db.Column(db.Float, nullable=False)
        status = db.Column(db.String(20), default='pending', index=True)
        buyer_email = db.Column(db.String(120), default='')
        buyer_name = db.Column(db.String(100), default='')
        buyer_ip = db.Column(db.String(45), default='')
        trade_no = db.Column(db.String(100), default='')
        payment_method = db.Column(db.String(20), default='alipay')
        pay_type = db.Column(db.String(30), default='alipay_page')
        qr_code = db.Column(db.Text, default='')
        pay_url = db.Column(db.Text, default='')
        paid_at = db.Column(db.DateTime, nullable=True)
        download_token = db.Column(db.String(64), unique=True, index=True)
        download_count = db.Column(db.Integer, default=0)
        max_downloads = db.Column(db.Integer, default=3)
        download_expire_hours = db.Column(db.Integer, default=24)
        expired_at = db.Column(db.DateTime, nullable=True)
        is_downloadable = db.Column(db.Boolean, default=True)
        last_download_ip = db.Column(db.String(45), default='')
        last_download_at = db.Column(db.DateTime, nullable=True)
        created_at = db.Column(db.DateTime, default=datetime.utcnow, index=True)
        updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)

        product = db.relationship('Product', backref='orders')

        @staticmethod
        def gen_order_id():
            return datetime.now().strftime('%Y%m%d%H%M%S') + secrets.token_hex(4).upper()

        def to_dict(self):
            username = '匿名用户'
            if self.user_id:
                try:
                    row = auth._user_by_id(self.user_id)
                    if row:
                        username = row["nickname"] or row["username"] or f"用户{self.user_id}"
                    else:
                        username = '已删除用户'
                except Exception:
                    username = '已删除用户'
            return {
                'id': self.id, 'order_id': self.order_id, 'amount': self.amount,
                'status': self.status, 'buyer_email': self.buyer_email, 'buyer_ip': self.buyer_ip,
                'download_count': self.download_count, 'max_downloads': self.max_downloads,
                'download_token': self.download_token, 'is_downloadable': self.is_downloadable,
                'paid_at': self.paid_at.isoformat() if self.paid_at else None,
                'expired_at': self.expired_at.isoformat() if self.expired_at else None,
                'created_at': self.created_at.isoformat() if self.created_at else None,
                'product_title': self.product.title if self.product else '',
                'remaining': max(0, self.max_downloads - self.download_count),
                'user_id': self.user_id,
                'username': username,
            }

    class DownloadLog(db.Model):
        __tablename__ = 'download_logs'
        id = db.Column(db.Integer, primary_key=True)
        order_id = db.Column(db.Integer, db.ForeignKey('orders.id'), nullable=False, index=True)
        ip_address = db.Column(db.String(45), default='')
        user_agent = db.Column(db.String(500), default='')
        file_size = db.Column(db.BigInteger, default=0)
        bytes_downloaded = db.Column(db.BigInteger, default=0)
        is_completed = db.Column(db.Boolean, default=False)
        created_at = db.Column(db.DateTime, default=datetime.utcnow)
        order = db.relationship('Order', backref='download_logs')

    return Product, Order, DownloadLog


# ============================================================
# 鉴权装饰器
# ============================================================
def get_current_auth_user():
    return auth.current_user()


def get_current_auth_user_id():
    u = auth.current_user()
    return u["id"] if u else None


def auth_user_to_dict(row):
    if not row:
        return None
    return {
        "id": row["id"], "username": row["username"],
        "phone": row["phone"], "nickname": row["nickname"],
        "avatar": row["avatar"],
    }


def is_admin_user():
    u = auth.current_user()
    if not u:
        return False
    return (u["username"] or "").lower() == (ADMIN_USERNAME or "").lower()


def auth_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        u = auth.current_user()
        if not u:
            return jsonify({"success": False, "message": "未登录或 token 失效",
                            "code": "AUTH_FAILED"}), 401
        request.auth_user = type("U", (), {
            "id": u["id"], "username": u["username"],
            "phone": u["phone"], "nickname": u["nickname"],
            "avatar": u["avatar"],
        })()
        return fn(*args, **kwargs)
    return wrapper


def admin_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        u = auth.current_user()
        if not u:
            return jsonify({"success": False, "message": "请登录",
                            "code": "AUTH_FAILED"}), 401
        if (u["username"] or "").lower() != (ADMIN_USERNAME or "").lower():
            return jsonify({"success": False, "message": "需要管理员权限",
                            "code": "AUTH_FAILED"}), 403
        request.auth_user = type("U", (), {
            "id": u["id"], "username": u["username"],
            "phone": u["phone"], "nickname": u["nickname"],
            "avatar": u["avatar"],
        })()
        return fn(*args, **kwargs)
    return wrapper


# ============================================================
# 主应用构建
# ============================================================
def create_app(configs):
    global app, db, auth, pay
    global FILES_FOLDER, STORAGE_FOLDER, FILES_DIR, STORAGE_DIR
    global BASE_URL, ADMIN_USERNAME, ADMIN_PASSWORD
    global DEFAULT_PRICE, DEFAULT_MAX_DOWNLOADS, DEFAULT_EXPIRE_HOURS

    flask_cfg = configs["flask"]
    db_cfg = configs["database"]
    biz_cfg = configs["business"]
    auth_cfg = configs["auth"]
    pay_cfg = configs["pay"]

    BASE_DIR = Path(os.getcwd()).absolute()
    for d in ("database", "files", "storage/files"):
        os.makedirs(BASE_DIR / d, exist_ok=True)

    FILES_FOLDER = str(BASE_DIR / "files")
    STORAGE_FOLDER = str(BASE_DIR / "storage" / "files")
    FILES_DIR = BASE_DIR / "files"
    STORAGE_DIR = BASE_DIR / "storage" / "files"

    BASE_URL = flask_cfg["BASE_URL"]
    ADMIN_USERNAME = biz_cfg["ADMIN_USERNAME"]
    ADMIN_PASSWORD = biz_cfg["ADMIN_PASSWORD"]
    DEFAULT_PRICE = biz_cfg["DEFAULT_PRICE"]
    DEFAULT_MAX_DOWNLOADS = biz_cfg["DEFAULT_MAX_DOWNLOADS"]
    DEFAULT_EXPIRE_HOURS = biz_cfg["DEFAULT_EXPIRE_HOURS"]

    # ---- 关键修复：把 sqlite 相对路径解析为绝对路径 ----
    db_url = db_cfg["DATABASE_URL"]
    if db_url.startswith("sqlite:///"):
        db_rel = db_url[len("sqlite:///"):]
        # 处理 sqlite:////absolute/path 这种四斜杠的绝对路径写法
        if db_rel.startswith("/"):
            db_rel = db_rel.lstrip("/")
            if os.path.isabs(db_rel):
                pass  # 已经是绝对路径
            else:
                db_rel = str(BASE_DIR / db_rel)
        elif not os.path.isabs(db_rel):
            db_rel = str(BASE_DIR / db_rel)
        db_url = "sqlite:///" + db_rel.replace("\\", "/")
    # ----------------------------------------------------

    # ---- 认证库路径也统一解析为绝对路径 ----
    auth_db_path = auth_cfg.get("AUTH_DB", "database/auth.db")
    if not os.path.isabs(auth_db_path):
        auth_db_path = str(BASE_DIR / auth_db_path)
    auth_cfg["AUTH_DB"] = auth_db_path
    # ----------------------------------------

    app = Flask(__name__)
    app.config['SECRET_KEY'] = flask_cfg["SECRET_KEY"]
    app.config['SESSION_COOKIE_SECURE'] = False
    app.config['SESSION_COOKIE_HTTPONLY'] = True
    app.config['SESSION_COOKIE_SAMESITE'] = 'Lax'
    app.config['SQLALCHEMY_DATABASE_URI'] = db_url
    app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
    app.config['MAX_CONTENT_LENGTH'] = 2 * 1024 * 1024 * 1024
    app.config['BASE_URL'] = BASE_URL
    app.config['ADMIN_USERNAME'] = ADMIN_USERNAME
    app.config['ADMIN_PASSWORD'] = ADMIN_PASSWORD
    app.config['DEFAULT_PRICE'] = DEFAULT_PRICE
    app.config['DEFAULT_MAX_DOWNLOADS'] = DEFAULT_MAX_DOWNLOADS
    app.config['DEFAULT_EXPIRE_HOURS'] = DEFAULT_EXPIRE_HOURS

    CORS(app, supports_credentials=True, origins=flask_cfg["CORS_ORIGINS"])

    db = SQLAlchemy(app)
    auth = AuthManager(app, config=auth_cfg)
    pay = Pay(pay_cfg)

    # 定义模型（在 db 初始化后）
    Product, Order, DownloadLog = define_models()

    # 注册所有路由
    register_routes(Product, Order, DownloadLog)

    # 初始化
    with app.app_context():
        db.create_all()
        init_dirs()
        create_sample_products(Product)
        auth.init_db()
        auth.init_routes()
        ensure_admin_account()

    return app

def init_dirs():
    """创建分类子目录"""
    categories = ['文档资料', '演示文稿', '编程源码', '图片素材', '视频资源',
                  '音频资源', '电子书', '压缩包', '其他资源']
    for cat in categories:
        os.makedirs(os.path.join(FILES_FOLDER, cat), exist_ok=True)
        os.makedirs(os.path.join(STORAGE_FOLDER, cat), exist_ok=True)


