    @app.route('/api/order/check/<oid>')
    @auth.rate_limit(scope="order_check", limit=30, window=60, by="ip")
    def api_check_order(oid):
        o = db.session.execute(select(Order).where(Order.order_id == oid)).scalar_one_or_none()
        if not o:
            return jsonify({'status': 'not_found'}), 404

        if o.status == 'pending':
            try:
                result = pay.query(o.pay_type, out_trade_no=o.order_id)
                if o.pay_type.startswith('alipay'):
                    if result.get('trade_status') in ('TRADE_SUCCESS', 'TRADE_FINISHED'):
                        o.status = 'paid'
                        o.trade_no = result.get('trade_no', '')
                        o.paid_at = datetime.utcnow()
                        product = db.session.get(Product, o.product_id)
                        if product:
                            product.sales_count += 1
                        db.session.commit()
                elif o.pay_type.startswith('wechat'):
                    if result.get('trade_state') == 'SUCCESS':
                        o.status = 'paid'
                        o.trade_no = result.get('transaction_id', '')
                        o.paid_at = datetime.utcnow()
                        product = db.session.get(Product, o.product_id)
                        if product:
                            product.sales_count += 1
                        db.session.commit()
            except Exception as e:
                logger.error(f'查询支付状态失败: {e}')

        return jsonify({
            'status': o.status,
            'download_url': f'{BASE_URL}/api/download/page/{o.download_token}' if o.status == 'paid' else None,
        })

