    @app.route('/api/admin/product/<int:pid>', methods=['GET', 'PUT', 'DELETE'])
    @admin_required
    def api_admin_product(pid):
        p = get_or_404(Product, pid)
        if request.method == 'GET':
            return jsonify({'success': True, 'product': p.to_dict()})
        elif request.method == 'PUT':
            d = request.get_json()
            if 'title' in d: p.title = str(d['title'])[:200]
            if 'description' in d: p.description = str(d.get('description', ''))
            if 'price' in d and d['price'] is not None:
                p.price = round(float(d['price']), 2)
            if 'original_price' in d:
                p.original_price = float(d['original_price']) if d['original_price'] else None
            if 'category' in d: p.category = str(d.get('category', ''))
            if 'tags' in d:
                tags_val = d['tags']
                p.tags = ','.join(tags_val) if isinstance(tags_val, list) else str(tags_val)
            if 'is_active' in d: p.is_active = bool(d['is_active'])
            if 'is_featured' in d: p.is_featured = bool(d['is_featured'])
            if 'max_downloads' in d: p.max_downloads = int(d['max_downloads'])
            if 'expire_hours' in d: p.expire_hours = int(d['expire_hours'])
            db.session.commit()
            return jsonify({'success': True, 'product': p.to_dict()})
        else:
            oids = db.session.execute(select(Order.id).where(Order.product_id == pid)).scalars().all()
            for oid in oids:
                db.session.execute(sqldelete(DownloadLog).where(DownloadLog.order_id == oid))
            db.session.execute(sqldelete(Order).where(Order.product_id == pid))
            try:
                fp = os.path.join(STORAGE_FOLDER, p.storage_path)
                if os.path.exists(fp):
                    os.remove(fp)
            except Exception:
                pass
            db.session.delete(p)
            db.session.commit()
            return jsonify({'success': True, 'message': '已删除'})

