    @app.route('/api/admin/upload', methods=['POST'])
    @admin_required
    @auth.rate_limit(scope="admin_upload", limit=10, window=60, by="user")
    def api_admin_upload():
        try:
            if 'file' not in request.files:
                return jsonify({'success': False, 'message': '没有选择文件'}), 400
            file = request.files['file']
            if file.filename == '':
                return jsonify({'success': False, 'message': '没有选择文件'}), 400

            title = request.form.get('title', '')
            description = request.form.get('description', '')
            category = request.form.get('category', '')
            price = float(request.form.get('price', DEFAULT_PRICE))
            original_price = request.form.get('original_price', None)
            if original_price:
                original_price = float(original_price)
            tags = request.form.get('tags', '')
            max_downloads = int(request.form.get('max_downloads', DEFAULT_MAX_DOWNLOADS))
            expire_hours = int(request.form.get('expire_hours', DEFAULT_EXPIRE_HOURS))
            is_featured = request.form.get('is_featured', 'false').lower() == 'true'

            if not title:
                title = os.path.splitext(file.filename)[0]
            if not category:
                category = get_category(file.filename)

            upload_dir = os.path.join(FILES_FOLDER, category)
            storage_dir = os.path.join(STORAGE_FOLDER, category)
            os.makedirs(upload_dir, exist_ok=True)
            os.makedirs(storage_dir, exist_ok=True)

            file_ext = os.path.splitext(file.filename)[1].lower()
            src_path = os.path.join(upload_dir, file.filename)
            file.save(src_path)

            storage_name = gen_uuid() + file_ext
            storage_path = os.path.join(storage_dir, storage_name)
            shutil.copy2(src_path, storage_path)
            try:
                os.chmod(storage_path, 0o444)
            except Exception:
                pass

            file_size = os.path.getsize(storage_path)
            file_hash = calc_hash(storage_path)

            product = Product(
                uuid=gen_uuid(), title=title, description=description,
                storage_path=os.path.join(category, storage_name),
                original_filename=file.filename, file_size=file_size,
                file_type=file_ext.replace('.', ''), file_hash=file_hash,
                mime_type=file.content_type or 'application/octet-stream',
                price=price, original_price=original_price, category=category,
                tags=tags, max_downloads=max_downloads, expire_hours=expire_hours,
                is_active=True, is_featured=is_featured
            )
            db.session.add(product)
            db.session.commit()
            return jsonify({'success': True, 'message': '文件上传成功', 'product': product.to_dict()})
        except Exception as e:
            db.session.rollback()
            return jsonify({'success': False, 'message': f'上传失败: {str(e)}'}), 500

