    @app.route('/api/admin/products/batch', methods=['POST'])
    @admin_required
    def api_batch():
        d = request.get_json()
        ids = d.get('ids', [])
        act = d.get('action', '')
        if not ids:
            return jsonify({'success': False, 'message': '请选择'}), 400
        if act == 'activate':
            db.session.execute(update(Product).where(Product.id.in_(ids)).values(is_active=True))
        elif act == 'deactivate':
            db.session.execute(update(Product).where(Product.id.in_(ids)).values(is_active=False))
        elif act == 'delete':
            for pid in ids:
                oids = db.session.execute(select(Order.id).where(Order.product_id == pid)).scalars().all()
                for oid in oids:
                    db.session.execute(sqldelete(DownloadLog).where(DownloadLog.order_id == oid))
                db.session.execute(sqldelete(Order).where(Order.product_id == pid))
            db.session.execute(sqldelete(Product).where(Product.id.in_(ids)))
        elif act == 'set_price':
            db.session.execute(update(Product).where(Product.id.in_(ids))
                               .values(price=float(d.get('price', 0))))
        db.session.commit()
        return jsonify({'success': True, 'message': '操作成功'})

    @app.route('/api/admin/scan')
    @admin_required
    def api_scan():
        res = []
        for root, dirs, files in os.walk(FILES_FOLDER):
            dirs[:] = [x for x in dirs if not x.startswith('.')]
            for fn in files:
                if fn.startswith('.'):
                    continue
                fp = os.path.join(root, fn)
                rp = os.path.relpath(fp, FILES_FOLDER)
                st = os.stat(fp)
                fh = calc_hash(fp)
                res.append({
                    'file_path': rp, 'file_name': fn, 'file_size': st.st_size,
                    'file_type': fn.rsplit('.', 1)[-1].lower() if '.' in fn else '',
                    'file_hash': fh, 'category': get_category(fn),
                    'exists': db.session.execute(
                        select(func.count(Product.id)).where(Product.file_hash == fh)
                    ).scalar() > 0
                })
        return jsonify({'success': True, 'files': res, 'total': len(res)})

    @app.route('/api/admin/scan/add', methods=['POST'])
    @admin_required
    def api_scan_add():
        d = request.get_json()
        files = d.get('files', [])
        price = float(d.get('price', DEFAULT_PRICE))
        use_cat = d.get('use_category_price', False)
        added = 0
        for f in files:
            if db.session.execute(
                select(func.count(Product.id)).where(Product.file_hash == f.get('file_hash', ''))
            ).scalar() > 0:
                continue
            src = os.path.join(FILES_FOLDER, f['file_path'])
            if not os.path.exists(src):
                continue
            sn = gen_uuid() + os.path.splitext(f['file_name'])[1].lower()
            cd = os.path.join(STORAGE_FOLDER, f.get('category', '其他'))
            os.makedirs(cd, exist_ok=True)
            dst = os.path.join(cd, sn)
            shutil.copy2(src, dst)
            try:
                os.chmod(dst, 0o444)
            except Exception:
                pass
            fp = CATEGORY_PRICES.get(f.get('category', '其他'), DEFAULT_PRICE) if use_cat else price
            p = Product(
                uuid=gen_uuid(),
                title=f['file_name'].rsplit('.', 1)[0].replace('_', ' ').replace('-', ' '),
                storage_path=os.path.join(f.get('category', '其他'), sn),
                original_filename=f['file_name'],
                file_size=f['file_size'], file_type=f['file_type'],
                file_hash=f['file_hash'], price=fp,
                category=f.get('category', ''), is_active=True
            )
            db.session.add(p)
            added += 1
        db.session.commit()
        return jsonify({'success': True, 'added': added,
                        'message': f'成功添加 {added} 个商品'})

